package ru.neverland.minttrade;
import java.util.*;
import ru.neverland.minttrade.guarantee.GuaranteeTerms;
public final class GuaranteeTermsSmoke {
    static int checks;static void check(boolean value,String why){checks++;if(!value)throw new AssertionError(why);}
    static void reject(Runnable action,String why){try{action.run();}catch(IllegalArgumentException expected){check(true,why);return;}throw new AssertionError(why);}
    public static void main(String[]args){var terms=new GuaranteeTerms(1000,100,60_000);check(terms.reserved(100_00)==10_00,"ten percent warranty comes from existing base escrow");check(terms.compensation(100_00,60_000)==0,"grace does not create compensation");check(terms.compensation(100_00,300_000)==4_00,"four paid late minutes return four percent");check(terms.compensation(100_00,30*86_400_000L)==10_00,"compensation never exceeds reserved seller share");check(terms.compensation(1,300_000)==0,"fractional cent rounds down without minting");check(GuaranteeTerms.none().compensation(100_00,300_000)==0,"legacy caravans keep their full original payout");reject(()->new GuaranteeTerms(10001,100,0),"reserve cannot exceed price");reject(()->new GuaranteeTerms(100,0,0),"enabled warranty needs a real rate");reject(()->terms.reserved(Long.MAX_VALUE),"overflowing price is rejected");var random=new Random(20261029);for(int i=0;i<10_000;i++){long price=Math.floorMod(random.nextLong(),GuaranteeTerms.MAX_CENTS+1);long delay=Math.floorMod(random.nextLong(),GuaranteeTerms.MAX_DURATION+1);var allocation=terms.allocate(price,delay);check(allocation.sellerCents()+allocation.buyerCompensationCents()==price&&allocation.buyerCompensationCents()<=allocation.reservedCents(),"seller plus buyer equals funded principal");}System.out.println("GuaranteeTermsSmoke PASS "+checks+" checks");}
}
